package com.taskmate.utils;
import com.taskmate.database.Database;import com.taskmate.security.PasswordHasher;import java.io.Console;import java.sql.*;import java.util.Arrays;
public class InitHod {
 public static void main(String[] args)throws Exception {Console console=System.console();if(console==null)throw new IllegalStateException("Run from a terminal so password input is not echoed.");String name=console.readLine("HOD name: "),email=console.readLine("HOD email: ");char[] pass=console.readPassword("New HOD password (12+ chars): ");if(pass.length<12)throw new IllegalArgumentException("Use at least 12 characters.");try(Connection c=Database.connect()){try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM users WHERE role='HOD'")){r.next();if(r.getInt(1)>0)throw new IllegalStateException("An HOD already exists. Ask the existing administrator to create another account.");}try(PreparedStatement p=c.prepareStatement("INSERT INTO users(name,email,password_hash,role,department) VALUES(?,?,?,'HOD','Computer Science')")){p.setString(1,name.trim());p.setString(2,email.trim().toLowerCase());p.setString(3,PasswordHasher.hash(pass));p.executeUpdate();System.out.println("Initial HOD account created.");}}finally{Arrays.fill(pass,'\0');}}
}
